SELECT ag.anime_id AS animeId, g.genre_id AS genreId, g.genre_kor AS genreName FROM genres g JOIN animegenres ag ON ag.genre_id = g.genre_id WHERE ag.anime_id IN
#{animeId}
ORDER BY ag.anime_id, g.genre_id

SELECT g.genre_id AS genreId
FROM genres AS g
WHERE g.genre_kor = #{genreName}
